/* Reutiliza exactamente la acción vigente de Limpiar en Repeat. */
(()=>{function init(){const input=document.getElementById('accountQuery'),x=document.getElementById('rp23-searchX'),clear=document.getElementById('rp78-searchClear');if(!input||!x||!clear)return;const sync=()=>{x.hidden=input.value.length===0};input.addEventListener('input',sync);input.addEventListener('change',sync);clear.addEventListener('click',sync);x.addEventListener('click',()=>{clear.click();sync();input.focus()});sync();}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();
